Request Payment Via STK Push.code:
// Prompt a member to pay their monthly health insurance contribution.
// BusinessShortCode, Password and Timestamp are added for you from the credential.
// This operation doesn't resolve $ references in its body, so build it inside fn().
fn(state =>
  stkPush({
    Amount: state.data.amount, // KES, whole shillings
    PartyA: state.data.phone, // payer, format 2547XXXXXXXX
    PartyB: state.configuration.short_code, // paybill receiving the funds
    PhoneNumber: state.data.phone, // phone that receives the PIN prompt
    CallBackURL: 'https://app.openfn.org/i/<your-webhook-id>', // receives the result
    AccountReference: state.data.memberNo, // max 12 characters, shown to the payer
    TransactionDesc: 'Monthly contribution',
  })(state)
);

Register C2B Callback URLs.code:
// Register the URLs M-Pesa calls when customers pay into your paybill.
// This operation doesn't resolve $ references in its body, so build it inside fn().
fn(state =>
  registerUrl({
    ShortCode: state.configuration.short_code,
    ResponseType: 'Completed', // what to do if the validation URL is unreachable
    ConfirmationURL: 'https://app.openfn.org/i/<confirmation-webhook-id>',
    ValidationURL: 'https://app.openfn.org/i/<validation-webhook-id>',
  })(state)
);

Pay Supplier Till.code:
// Pay a pharmacy supplier's till for a medicines order.
// This operation doesn't resolve $ references in its body, so build it inside fn().
// initiatorName and securityCredential are extra fields added to the M-Pesa credential.
fn(state =>
  buyGoods({
    Initiator: state.configuration.initiatorName, // API operator username
    SecurityCredential: state.configuration.securityCredential, // encrypted operator password
    Amount: state.data.amount,
    PartyA: state.configuration.short_code, // your shortcode (money leaves here)
    PartyB: state.data.supplierTill, // supplier's till number
    AccountReference: state.data.orderNo, // up to 13 characters
    Requester: state.data.requesterPhone, // optional, 2547XXXXXXXX
    Remarks: 'Medicines order payment',
    QueueTimeOutURL: 'https://app.openfn.org/i/<timeout-webhook-id>',
    ResultURL: 'https://app.openfn.org/i/<result-webhook-id>',
  })(state)
);

Remit Tax To KRA.code:
// Remit tax to KRA using a payment registration number (PRN).
// This operation doesn't resolve $ references in its body, so build it inside fn().
// initiatorName and securityCredential are extra fields added to the M-Pesa credential.
fn(state =>
  remitTax({
    Initiator: state.configuration.initiatorName,
    SecurityCredential: state.configuration.securityCredential,
    Amount: state.data.taxAmount,
    PartyA: state.configuration.short_code,
    AccountReference: state.data.prn, // PRN issued by KRA
    Remarks: 'Monthly PAYE remittance',
    QueueTimeOutURL: 'https://app.openfn.org/i/<timeout-webhook-id>',
    ResultURL: 'https://app.openfn.org/i/<result-webhook-id>',
  })(state)
);

Request STK Push For Each Member.code:
// Send an STK push to each member in the incoming list.
// stkPush doesn't resolve $ references in its body, so build it inside fn().
each(
  $.data.members,
  // Inside each(), state.data is the current member.
  fn(state =>
    stkPush({
      Amount: state.data.amount,
      PartyA: state.data.phone,
      PartyB: state.configuration.short_code,
      PhoneNumber: state.data.phone,
      CallBackURL: 'https://app.openfn.org/i/<your-webhook-id>',
      AccountReference: state.data.memberNo,
      TransactionDesc: 'Savings group contribution',
    })(state)
  )
);

